CREATE OR REPLACE FUNCTION priv.check_process()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'api'
AS $function$
DECLARE
    old_name text := (SELECT name FROM api.status WHERE id = OLD.status_id);
    new_name text := (SELECT name FROM api.status WHERE id = NEW.status_id);
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF new_name <> 'Черновик' THEN
            RAISE EXCEPTION 'новая заявка создаётся в статусе «Черновик»' USING ERRCODE = 'check_violation';
        END IF;
    ELSIF NEW.status_id IS DISTINCT FROM OLD.status_id AND (old_name, new_name) NOT IN (
            ('Черновик', 'Подана'), ('Подана', 'На экспертизе'),
            ('На экспертизе', 'Одобрена'), ('На экспертизе', 'Отклонена')) THEN
        RAISE EXCEPTION 'переход «%» → «%» запрещён', old_name, new_name USING ERRCODE = 'check_violation';
    END IF;
    IF new_name IN ('Одобрена', 'Отклонена') AND coalesce(btrim(NEW.verdict), '') = '' THEN
        RAISE EXCEPTION 'решение без заключения эксперта' USING ERRCODE = 'check_violation';
    END IF;
    IF new_name = 'Одобрена' AND NEW.amount > (SELECT funding_limit FROM api.company WHERE id = NEW.company_id) THEN
        RAISE EXCEPTION 'сумма больше лимита компании' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $function$

args.query:
alter table api.company add column if not exists ref_key uuid unique;
update api.app_user set role='lawyer' where login='lawyer1';

create table api.contract(
  number text primary key,
  application_id integer not null references api.application(id),
  amount numeric not null check (amount>0),
  signed_on date,
  status text not null default 'Проект' check (status in ('Проект','Подписан'))
);
create index on api.contract(application_id);

create function priv.check_contract() returns trigger language plpgsql security definer set search_path to 'api' as $$
begin
  if not exists (select 1 from api.application a join api.status s on s.id=a.status_id where a.id=new.application_id and s.name='Одобрена') then
    raise exception 'договор можно заключить только по одобренной заявке' using errcode='check_violation';
  end if;
  return new;
end $$;
create trigger check_contract before insert or update on api.contract for each row execute function priv.check_contract();

create function priv.contract_company(app int) returns int language sql stable security definer set search_path to 'api' as $$ select company_id from api.application where id=app $$;

alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using (true) with check (true);
create policy lawyer_read on api.contract for select to lawyer using (true);
create policy lawyer_ins on api.contract for insert to lawyer with check (true);
create policy lawyer_upd on api.contract for update to lawyer using (true) with check (true);
create policy applicant_read on api.contract for select to applicant using (priv.contract_company(application_id)=priv.my_company());

grant select,insert,update,delete on api.contract to fund_admin;
grant select,insert,update on api.contract to lawyer;
grant select on api.contract to applicant;
grant usage on schema priv to lawyer;
grant execute on function priv.contract_company(int) to applicant;

grant select on api.application, api.company, api.status to lawyer;
grant select on api.app_user to lawyer;
revoke select on api.app_user from lawyer;

create view api.limit_balance with (security_invoker=true) as
select c.name as company, c.funding_limit, ap.approved,
  coalesce(ct.contracted,0) as contracted,
  c.funding_limit - coalesce(ct.contracted,0) as remaining
from api.company c
join (select a.company_id, sum(a.amount) approved from api.application a join api.status s on s.id=a.status_id where s.name='Одобрена' group by 1) ap on ap.company_id=c.id
left join (select a.company_id, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_id=c.id;
grant select on api.limit_balance to fund_admin, lawyer, applicant;
notify pgrst,'reload schema';
select has_function_privilege('applicant','priv.my_company()','execute'), has_schema_privilege('applicant','priv','usage');
